#include <iostream>
#include <cstdlib>

class Fraction {
    int n, d;
    static int gcdi(int a, int b) { return b == 0 ? a : gcdi(b, a % b); }
    void norm() {
        if (d < 0) { n = -n; d = -d; }
        int g = gcdi(std::abs(n), d);
        if (g > 1) { n /= g; d /= g; }
    }
public:
    Fraction(int num = 0, int den = 1) : n(num), d(den) { norm(); }
    friend Fraction operator+(const Fraction& a, const Fraction& b) {
        return Fraction(a.n * b.d + b.n * a.d, a.d * b.d);
    }
    friend Fraction operator*(const Fraction& a, const Fraction& b) {
        return Fraction(a.n * b.n, a.d * b.d);
    }
    friend Fraction operator-(const Fraction& a) {
        return Fraction(-a.n, a.d);
    }
    friend bool operator<(const Fraction& a, const Fraction& b) {
        return a.n * b.d < b.n * a.d;
    }
    friend bool operator==(const Fraction& a, const Fraction& b) {
        return a.n == b.n && a.d == b.d;
    }
    friend std::ostream& operator<<(std::ostream& os, const Fraction& f) {
        if (f.d == 1) return os << f.n;
        return os << f.n << "/" << f.d;
    }
};

Fraction harmonic(int k) {
    if (k <= 0) return Fraction(0);
    return harmonic(k - 1) + Fraction(1, k);
}

int main() {
    Fraction arr[6] = {Fraction(3, 4), Fraction(-1, 2), Fraction(6, -8), Fraction(5, 10), Fraction(7), Fraction(0, 5)};
    for (int i = 0; i < 6; ++i)
        for (int j = 0; j + 1 < 6 - i; ++j)
            if (arr[j + 1] < arr[j]) {
                Fraction t = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = t;
            }
    for (int i = 0; i < 6; ++i) std::cout << arr[i] << (i + 1 < 6 ? " " : "");
    std::cout << std::endl;
    for (int k = 0; k <= 5; ++k) std::cout << "H(" << k << ")=" << harmonic(k) << std::endl;
    Fraction a(1, 2), b(2, 4);
    std::cout << std::boolalpha << (a == b) << " " << (a < b) << " " << (-a * b) << std::endl;
    const Fraction& r = arr[4];
    std::cout << r + r << " " << (r * Fraction(2, 3) + Fraction(1, 3)) << std::endl;
    return 0;
}

#include <iostream>

class Matrix {
    long long m[2][2];
public:
    Matrix(long long a = 1, long long b = 0, long long c = 0, long long d = 1) {
        m[0][0] = a; m[0][1] = b; m[1][0] = c; m[1][1] = d;
    }
    friend Matrix operator*(const Matrix& x, const Matrix& y) {
        Matrix r(0, 0, 0, 0);
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < 2; ++j)
                for (int k = 0; k < 2; ++k)
                    r.m[i][j] += x.m[i][k] * y.m[k][j];
        return r;
    }
    friend Matrix power(const Matrix& base, int e) {
        if (e == 0) return Matrix();
        if (e % 2 == 1) return base * power(base, e - 1);
        Matrix h = power(base, e / 2);
        return h * h;
    }
    friend long long trace(const Matrix& x) { return x.m[0][0] + x.m[1][1]; }
    friend std::ostream& operator<<(std::ostream& os, const Matrix& x) {
        for (int i = 0; i < 2; ++i) {
            os << "[";
            for (int j = 0; j < 2; ++j) os << (j ? " " : "") << x.m[i][j];
            os << "]";
        }
        return os;
    }
};

int main() {
    Matrix fib(1, 1, 1, 0);
    for (int n = 0; n <= 10; n += 2) {
        Matrix p = power(fib, n);
        std::cout << "n=" << n << " " << p << " trace=" << trace(p) << std::endl;
    }
    Matrix big = power(fib, 80);
    std::cout << big << std::endl;
    Matrix id;
    Matrix* ptr = &id;
    std::cout << (*ptr * fib) << " " << power(*ptr, 5) << std::endl;
    Matrix list[3] = {fib, fib * fib, power(fib, 3)};
    long long s = 0;
    for (const Matrix& q : list) s += trace(q);
    std::cout << "sum traces=" << s << std::endl;
    return 0;
}

#include <iostream>

class Segment;

class Vec3 {
    int v[3];
public:
    Vec3(int x = 0, int y = 0, int z = 0) { v[0] = x; v[1] = y; v[2] = z; }
    friend Vec3 operator+(const Vec3& a, const Vec3& b) {
        return Vec3(a.v[0] + b.v[0], a.v[1] + b.v[1], a.v[2] + b.v[2]);
    }
    friend Vec3 operator-(const Vec3& a) { return Vec3(-a.v[0], -a.v[1], -a.v[2]); }
    friend Vec3 operator*(int k, const Vec3& a) { return Vec3(k * a.v[0], k * a.v[1], k * a.v[2]); }
    friend Vec3 operator*(const Vec3& a, int k) { return k * a; }
    friend Vec3& operator+=(Vec3& a, const Vec3& b) {
        for (int i = 0; i < 3; ++i) a.v[i] += b.v[i];
        return a;
    }
    friend int dot(const Vec3& a, const Vec3& b) {
        int s = 0;
        const int* p = a.v;
        const int* q = b.v;
        while (p != a.v + 3) s += *p++ * *q++;
        return s;
    }
    friend std::ostream& operator<<(std::ostream& os, const Vec3& a) {
        return os << "(" << a.v[0] << "," << a.v[1] << "," << a.v[2] << ")";
    }
    friend class Segment;
};

class Segment {
    Vec3 from, to;
public:
    Segment(const Vec3& f, const Vec3& t) : from(f), to(t) {}
    friend int lengthSq(const Segment& s) {
        int total = 0;
        for (int i = 0; i < 3; ++i) {
            int diff = s.to.v[i] - s.from.v[i];
            total += diff * diff;
        }
        return total;
    }
    friend bool operator<(const Segment& a, const Segment& b) { return lengthSq(a) < lengthSq(b); }
    friend std::ostream& operator<<(std::ostream& os, const Segment& s) {
        return os << s.from << "->" << s.to << " len2=" << lengthSq(s);
    }
};

int main() {
    Vec3 a(1, 2, 3), b(-4, 5, 0);
    std::cout << a + b << " " << -a << " " << 3 * b << " " << a * 2 << std::endl;
    Vec3 acc;
    Vec3& ref = acc;
    for (int i = 1; i <= 4; ++i) (ref += i * a) += b;
    std::cout << acc << " dot=" << dot(acc, a) << std::endl;
    Segment segs[3] = {Segment(a, b), Segment(Vec3(), a), Segment(b, acc)};
    int best = 0;
    for (int i = 1; i < 3; ++i)
        if (segs[best] < segs[i]) best = i;
    for (const Segment& s : segs) std::cout << s << std::endl;
    std::cout << "longest=" << best << std::endl;
    return 0;
}

#include <iostream>

class IntList {
    struct Node {
        int val;
        Node* next;
        Node(int v, Node* n) : val(v), next(n) {}
    };
    Node* head;
    static Node* copyChain(const Node* p) {
        if (!p) return nullptr;
        return new Node(p->val, copyChain(p->next));
    }
    static void freeChain(Node* p) {
        while (p) { Node* t = p->next; delete p; p = t; }
    }
public:
    IntList() : head(nullptr) {}
    IntList(const IntList& o) : head(copyChain(o.head)) {}
    IntList& operator=(const IntList& o) {
        if (this != &o) { freeChain(head); head = copyChain(o.head); }
        return *this;
    }
    ~IntList() { freeChain(head); }
    void pushFront(int v) { head = new Node(v, head); }
    friend std::ostream& operator<<(std::ostream& os, const IntList& l) {
        os << "{";
        for (const Node* p = l.head; p; p = p->next) os << p->val << (p->next ? ", " : "");
        return os << "}";
    }
    friend bool operator==(const IntList& a, const IntList& b) {
        const Node* p = a.head;
        const Node* q = b.head;
        while (p && q) {
            if (p->val != q->val) return false;
            p = p->next;
            q = q->next;
        }
        return p == nullptr && q == nullptr;
    }
    friend bool operator!=(const IntList& a, const IntList& b) { return !(a == b); }
    friend IntList mergeSorted(const IntList& a, const IntList& b) {
        IntList r;
        Node** tail = &r.head;
        const Node* p = a.head;
        const Node* q = b.head;
        while (p || q) {
            int v;
            if (!q || (p && p->val <= q->val)) { v = p->val; p = p->next; }
            else { v = q->val; q = q->next; }
            *tail = new Node(v, nullptr);
            tail = &(*tail)->next;
        }
        return r;
    }
    friend int sumRec(const IntList& l, const Node* p) {
        return p ? p->val + sumRec(l, p->next) : 0;
    }
    friend int total(const IntList& l) { return sumRec(l, l.head); }
};

int main() {
    IntList a, b;
    for (int v : {9, 7, 5, 1}) a.pushFront(v);
    for (int v : {10, 8, 4, 4, 2}) b.pushFront(v);
    std::cout << a << " " << b << std::endl;
    IntList m = mergeSorted(a, b);
    std::cout << m << " total=" << total(m) << std::endl;
    IntList c = m;
    std::cout << std::boolalpha << (c == m) << " " << (c != a) << std::endl;
    c.pushFront(0);
    std::cout << (c == m) << " " << c << std::endl;
    IntList empty;
    std::cout << empty << " " << (empty == IntList()) << " " << total(mergeSorted(empty, a)) << std::endl;
    return 0;
}
